    {
        "$match": {
            "data_description.project_name": "Thalamus in the middle"
        }
    },
    {
        "$unwind": "$procedures.subject_procedures"
    },
    {
        "$unwind": "$procedures.subject_procedures.procedures"
    },
    {
        "$group": {
            "_id": "$procedures.subject_procedures.procedures.targeted_structure"
